71: /// Read and judge every recovery record of the task (`Read-TaskPendingRecords` + the
72: /// `Recovered` flag from `Get-NextNumbers`). (Wave 7c, F40-1) A listing of the records that failed
73: /// (the codex home's kill records cannot be listed: [`pending::PendingPaths::error`]) is the
74: /// error, before any record is judged - a real run, a dry run and the panel refuse on it.
75: pub fn assess(store: &FilesStore, task: &TaskSlug) -> Recovery {
76:     let task_dir = store.task_dir(task);
77:     // Ledger `n`s (for the recovered/cleared distinction).
78:     let ledger_ns: HashSet<i64> = store
