85:     let mut items = Vec::new();
86:     let listed = pending::pending_paths(&task_dir);
87:     if let Some(err) = listed.error {
88:         return Recovery {
89:             error: Some(err),
90:             items,
91:         };
92:     }
93:     for path in listed.paths {
94:         let rd = pending::read_pending_file(&path);
95:         if let Some(err) = rd.error {
96:             return Recovery {
97:                 error: Some(err),
98:                 items,
99:             };
100:         }
101:         let record = match rd.record {
102:             Some(r) => r,
103:             None => continue,
104:         };
105:         let check = pending::test_pending_active(&record, &path);
106:         let name = path
107:             .file_name()
108:             .map(|n| n.to_string_lossy().to_string())
109:             .unwrap_or_default();
110:         let state = record
111:             .get("state")
112:             .and_then(|v| v.as_str())
