120:                 other => other.to_string(),
121:             })
122:             .unwrap_or_default();
123:         // Recovered: n>0 with no ledger entry, or (no usable n) an nn that is present.
124:         let recovered = if n > 0 {
125:             !ledger_ns.contains(&n)
126:         } else {
127:             !nn.is_empty()
128:         };
129:         // (wave 9b, F66-1) another detached single run's record is harmless ONLY when its owning
130:         // bridge is proven alive (the live-writer verdict) in an ordinary lifecycle state and the
131:         // record names no survivor, unverified process or unconfirmed kill; every other active
132:         // record (an orphan, survivors, unverified, kill_unconfirmed, a dead bridge) blocks as
133:         // before wave 9.
134:         let nonempty = |k: &str| {
135:             record
136:                 .get(k)
