144:             && !nonempty("survivors")
145:             && !nonempty("unverified")
146:             && !record
147:                 .get("kill_unconfirmed")
148:                 .is_some_and(|v| !v.is_null() && v != &serde_json::Value::Bool(false));
149:         items.push(RecoveryItem {
150:             path,
