147: /// `Test-PidAlive`: a pid is alive when a process with that id exists and â€” if a start time
148: /// was recorded â€” still has that start time (otherwise the pid was reused).
149: pub fn pid_alive(pid: u32, start_time: &str) -> bool {
150:     if pid == 0 {
151:         return false;
152:     }
153:     let live = match process_start_iso(pid) {
154:         Some(s) => s,
155:         None => return false,
156:     };
157:     if !start_time.is_empty() && !live.is_empty() && !same_start_time(&live, start_time) {
158:         return false;
159:     }
160:     true
